import {readResponseJson, readResponseBlob, ResponseLimitError} from "./boundedResponse";
import {MAX_AUDIO_BYTES, MAX_JSON_BYTES, MAX_ERROR_BYTES} from "@/lib/resource/limits";
import {canonicalizeAudioTaskIds, isAudioTaskId} from "@/lib/audioGeneration/taskIds";
import {z} from "zod";
import {MUSIC_DURATION_LIMITS} from "@/domain/music";
import type {ApimartCredentials, ApimartFailure, ApimartRequestOptions, ApimartResult} from "./apimart";
import {normalizeBaseUrl} from "./openaiCompatible";
import {redactCredentials} from "./safeError";

export const SPEECH_VOICES = ["alloy", "echo", "fable", "onyx", "nova", "shimmer"] as const;
const unicode = (max: number) => z.string().refine(value => [...value].length <= max, `最多 ${max} 个字符`);
export const speechInputSchema = z.object({
    model: z.literal("gpt-4o-mini-tts"), input: unicode(4096).refine(value => !!value.trim(), "请输入配音文字"),
    voice: z.enum(SPEECH_VOICES), response_format: z.enum(["wav", "opus", "aac", "flac", "pcm"]),
    speed: z.number().finite().min(.25).max(4).optional(),
}).strict();
export const flowMusicInputSchema = z.object({
    model: z.literal("flowmusic"),
    sound_prompt: z.string().optional(),
    lyrics: z.string().optional(),
    title: z.string().optional(),
    bpm: z.string().refine(value => value.trim() !== "" && Number.isFinite(Number(value)) && Number(value) >= 1, "BPM 必须至少为 1").optional(),
    length: z.number().int("音乐时长必须为整数秒").min(MUSIC_DURATION_LIMITS.flowmusic.min).max(MUSIC_DURATION_LIMITS.flowmusic.max).optional(),
    seed: z.string().optional(),
}).strict().refine(value => !!(value.sound_prompt?.trim() || value.lyrics?.trim()), "请填写风格描述或歌词");
export const sunoMusicInputSchema = z.object({
    model: z.literal("suno"),
    version: z.enum(["v6", "v6-wild", "v6-mini"]),
    custom: z.boolean(),
    instrumental: z.boolean(),
    prompt: unicode(5000).optional(),
    title: unicode(80).optional(),
    style: unicode(1000).optional(),
    negative_tags: z.string().optional(),
    auto_lyrics: z.boolean().optional(),
    vocal_gender: z.enum(["Male", "Female"]).optional(),
    style_weight: z.number().finite().min(0).max(1).optional(),
    weirdness_constraint: z.number().finite().min(0).max(1).optional(),
    audio_weight: z.number().finite().min(0).max(1).optional(),
    variety: z.enum(["off", "normal", "high", "extra", "max"]).optional(),
    max_mode: z.boolean().optional(),
    audio_format: z.enum(["mp3", "m4a", "wav"]).optional(),
    duration: z.number().int("音乐时长必须为整数秒").min(MUSIC_DURATION_LIMITS.suno.min).max(MUSIC_DURATION_LIMITS.suno.max).optional(),
}).strict().superRefine((value, ctx) => {
    const issue = (message: string) => ctx.addIssue({code: "custom", message});
    if ((!value.custom || !value.instrumental) && !value.prompt?.trim()) issue("请填写创作描述或歌词");
    if (!value.custom && [...(value.prompt ?? "")].length > 3000) issue("灵感描述最多 3000 个字符");
    if (!value.custom && [value.title, value.style, value.negative_tags, value.auto_lyrics, value.duration, value.max_mode].some(field => field !== undefined)) issue("标题、风格、歌词调整、时长和 Max 模式仅适用于自定义模式");
});
export type SpeechInput = z.infer<typeof speechInputSchema>;
export type FlowMusicInput = z.infer<typeof flowMusicInputSchema>;
export type SunoMusicInput = z.infer<typeof sunoMusicInputSchema>;
export type MusicInput = FlowMusicInput | SunoMusicInput;
export const musicInputSchema = z.union([flowMusicInputSchema, sunoMusicInputSchema]);

export interface MusicResultTrack {
    /** Provider array position, one-based; never derive from a sorted/filtered list. */
    audioIndex: number;
    clipId?: string;
    audioId?: string;
    title: string;
    lyrics?: string;
    duration?: number;
    audioUrl: string;
    wavUrl?: string;
    imageUrl?: string;
}

export interface MusicTask {
    id: string;
    status: "pending" | "processing" | "completed" | "failed" | "unknown";
    providerStatus: string;
    progress?: number;
    tracks: MusicResultTrack[];
    cost?: number;
    creditsCost?: number;
    error?: string;
}

const record = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const finite = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const nonempty = (v: unknown): v is string => typeof v === "string" && !!v.trim();

function safeUrl(v: unknown): v is string {
    if (!nonempty(v)) return false;
    try {
        const u = new URL(v);
        return ["https:", "http:"].includes(u.protocol) && !u.username && !u.password;
    } catch {
        return false;
    }
}

const failure = (kind: ApimartFailure["kind"], message: string): ApimartFailure => ({ok: false, kind, message});
const aborted = (error: unknown, signal?: AbortSignal) => signal?.aborted || (error instanceof Error || error instanceof DOMException) && error.name === "AbortError";
const protocol = () => failure("protocol", "APIMart 音频响应不符合接口约定；请保留任务记录，不要自动重复提交");

async function audioRequest(credentials: ApimartCredentials, path: string, input: SpeechInput | MusicInput | undefined, options: ApimartRequestOptions): Promise<ApimartResult<{
    response: Response
}>> {
    const base = normalizeBaseUrl(credentials.baseUrl), key = credentials.apiKey.trim();
    if (!key || !safeUrl(base) || new URL(base).search || new URL(base).hash) return failure("validation", "请配置有效的 APIMart 地址和 API Key");
    if (options.signal?.aborted) return failure("aborted", "请求已停止；远端生成不会因此取消");
    try {
        const response = await (options.fetchImpl ?? fetch)(`${base}${path}`, {
            method: input ? "POST" : "GET",
            headers: {Authorization: `Bearer ${key}`, ...(input ? {"Content-Type": "application/json"} : {})},
            ...(input ? {body: JSON.stringify(input)} : {}),
            signal: options.signal,
            credentials: "omit",
            redirect: "error",
        });
        if (!response.ok) {
            let body: unknown;
            try {
                body = await readResponseJson(response, MAX_ERROR_BYTES, options.signal);
            } catch (error) {
                if (aborted(error, options.signal)) return failure("aborted", "请求已停止；远端生成不会因此取消");
                /* HTTP status remains authoritative for other body failures. */
            }
            const error = record(body) && record(body.error) ? body.error : undefined;
            const detail = typeof error?.message === "string" ? redactCredentials(error.message, key).slice(0, 300) : "请检查连接权限、余额和请求参数";
            return {
                ok: false,
                kind: "http",
                httpStatus: response.status,
                message: `APIMart 请求失败（${response.status}）：${detail}`
            };
        }
        return {ok: true, response};
    } catch (error) {
        return failure(aborted(error, options.signal) ? "aborted" : "network", "音频请求未能完成；提交结果可能尚未确认，请勿自动重复生成");
    }
}

async function jsonEnvelope(credentials: ApimartCredentials, path: string, input: MusicInput | undefined, options: ApimartRequestOptions): Promise<ApimartResult<{
    data: unknown
}>> {
    const result = await audioRequest(credentials, path, input, options);
    if (!result.ok) return result;
    let body: unknown;
    try {
        body = await readResponseJson(result.response, MAX_JSON_BYTES, options.signal);
    } catch (error) {
        if (aborted(error, options.signal)) return failure("aborted", "请求已停止；远端生成不会因此取消");
        return error instanceof ResponseLimitError ? failure("protocol", error.message) : protocol();
    }
    if (!record(body)) return protocol();
    if (body.error != null || body.success === false || (body.code !== undefined && body.code !== 200)) {
        const message = record(body.error) ? body.error.message : body.message;
        return failure("provider", typeof message === "string" ? redactCredentials(message, credentials.apiKey).slice(0, 300) : "APIMart 音频任务失败");
    }
    return body.code === 200 ? {ok: true, data: body.data} : protocol();
}

function speechReadFailure(error: unknown, signal?: AbortSignal): ApimartFailure {
    if (aborted(error, signal)) return failure("aborted", "请求已停止；远端生成不会因此取消");
    const message = error instanceof ResponseLimitError
        ? "配音响应超过本地读取限制（音频 32 MiB / JSON 4 MiB）；不会自动重新生成"
        : "未能读取完整的配音文件；不会自动重新生成";
    return failure("protocol", message);
}

export async function generateApimartSpeech(credentials: ApimartCredentials, input: SpeechInput, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    blob: Blob
}>> {
    const parsed = speechInputSchema.safeParse(input);
    if (!parsed.success) return failure("validation", parsed.error.issues[0]?.message ?? "配音参数无效");
    const result = await audioRequest(credentials, "/audio/speech", parsed.data, options);
    if (!result.ok) return result;
    try {
        const isJson = result.response.headers.get("content-type")?.includes("application/json");
        const blob = await readResponseBlob(result.response, isJson ? MAX_JSON_BYTES : MAX_AUDIO_BYTES, options.signal);
        const mime = blob.type.split(";")[0];
        if (mime === "application/json") {
            const body: unknown = JSON.parse(await blob.text());
            const message = record(body) && record(body.error) ? body.error.message : undefined;
            return failure("provider", typeof message === "string" ? redactCredentials(message, credentials.apiKey).slice(0, 300) : "APIMart 未返回配音文件");
        }
        if (!blob.size || (mime && !mime.startsWith("audio/") && mime !== "application/octet-stream")) return protocol();
        const mimeTypes = {wav: "audio/wav", opus: "audio/ogg", aac: "audio/aac", flac: "audio/flac", pcm: "audio/pcm"};
        return {
            ok: true,
            blob: new Blob([blob], {type: mime?.startsWith("audio/") ? blob.type : mimeTypes[input.response_format]})
        };
    } catch (error) {
        return speechReadFailure(error, options.signal);
    }
}

export async function submitApimartMusic(credentials: ApimartCredentials, input: MusicInput, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    taskIds: string[]
}>> {
    const parsed = musicInputSchema.safeParse(input);
    if (!parsed.success) return failure("validation", parsed.error.issues[0]?.message ?? "音乐参数无效");
    const result = await jsonEnvelope(credentials, "/music/generations", parsed.data, options);
    if (!result.ok) return result;
    if (!Array.isArray(result.data) || !result.data.length || !result.data.every(record)) return protocol();
    try {
        return {ok: true, taskIds: canonicalizeAudioTaskIds(result.data.map(row => row.task_id))};
    } catch {
        return protocol();
    }
}

export async function getApimartMusicTask(credentials: ApimartCredentials, taskId: string, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    task: MusicTask
}>> {
    if (!isAudioTaskId(taskId)) return failure("validation", "音乐任务 ID 无效；请保留任务记录，不要重复提交");
    const result = await jsonEnvelope(credentials, `/music/tasks/${encodeURIComponent(taskId)}?language=zh`, undefined, options);
    if (!result.ok) return result;
    const row = result.data;
    if (!record(row) || row.id !== taskId || !nonempty(row.status)) return protocol();
    const statuses = ["pending", "processing", "completed", "failed"];
    const status = statuses.includes(row.status) ? row.status as MusicTask["status"] : "unknown";
    const tracks: MusicResultTrack[] = [];
    const diagnostics: string[] = [];
    const music = record(row.result) ? row.result.music : undefined;
    if (status === "completed") {
        if (!Array.isArray(music) || !music.length) return protocol();
        for (const [index, track] of music.entries()) {
            if (!record(track) || !safeUrl(track.audio_url)) {
                diagnostics.push(`第 ${index + 1} 首音频缺少有效下载地址`);
                continue;
            }
            const rawDuration = track.duration ?? track.duration_seconds;
            const duration = typeof rawDuration === "string" && rawDuration.trim() ? Number(rawDuration) : rawDuration;
            tracks.push({
                audioIndex: index + 1, audioUrl: track.audio_url,
                title: typeof track.title === "string" ? track.title : `作品 ${index + 1}`,
                ...(nonempty(track.clip_id) ? {clipId: track.clip_id} : {}), ...(nonempty(track.audio_id) ? {audioId: track.audio_id} : {}),
                ...(typeof track.lyrics === "string" ? {lyrics: track.lyrics} : {}),
                ...(finite(duration) && duration > 0 ? {duration} : {}),
                ...(safeUrl(track.wav_url) ? {wavUrl: track.wav_url} : {}), ...(safeUrl(track.image_url) ? {imageUrl: track.image_url} : {}),
            });
        }
    }
    return {
        ok: true, task: {
            id: taskId, status, providerStatus: row.status, tracks,
            ...(finite(row.progress) ? {progress: Math.max(0, Math.min(100, row.progress))} : {}),
            ...(finite(row.cost) ? {cost: row.cost} : {}), ...(finite(row.credits_cost) ? {creditsCost: row.credits_cost} : {}),
            ...(diagnostics.length ? {error: diagnostics.join("；")} : record(row.error) && typeof row.error.message === "string" ? {error: redactCredentials(row.error.message, credentials.apiKey).slice(0, 300)} : {}),
        }
    };
}

/** CDN downloads never receive the connector's bearer token. */
export async function downloadApimartAudio(url: string, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    blob: Blob
}>> {
    if (!safeUrl(url)) return failure("validation", "音频下载地址无效");
    try {
        const response = await (options.fetchImpl ?? fetch)(url, {
            signal: options.signal,
            credentials: "omit",
            redirect: "error"
        });
        if (!response.ok) {
            await response.body?.cancel().catch(() => undefined);
            return failure("http", `音频下载失败（${response.status}），可以重试下载`);
        }
        const blob = await readResponseBlob(response, MAX_AUDIO_BYTES, options.signal);
        if (!blob.size || (blob.type && !blob.type.startsWith("audio/") && blob.type !== "application/octet-stream")) return protocol();
        return {ok: true, blob};
    } catch (error) {
        if (aborted(error, options.signal)) return failure("aborted", "音频下载已停止；无需重新生成");
        if (error instanceof ResponseLimitError) return failure("protocol", "音频下载超过本地 32 MiB 限制，已停止读取；保留任务记录，不会重新生成");
        return failure("network", "音频下载未完成，请重试下载；无需重新生成");
    }
}

import {isReadAbort, readErrorText, readResponseText, ResponseLimitError} from "./boundedResponse";
import {MAX_AUDIO_BYTES, MAX_JSON_BYTES, MAX_ERROR_BYTES, MAX_SPEECH_ENVELOPE_BYTES} from "@/lib/resource/limits";
import type {MimoSpeechSettings} from "@/domain/audio";
import {detectAudioMime} from "@/lib/audio/mime";
import {collectModelMetadata, parseModelMetadata} from "./modelMetadata";
import {type ListModelsResult, normalizeBaseUrl} from "./openaiCompatible";
import {redactCredentials} from "./safeError";

export const MIMO_VOICES = ["mimo_default", "冰糖", "茉莉", "苏打", "白桦", "Mia", "Chloe", "Milo", "Dean"] as const;
export const MIMO_MODELS = {
    preset: "mimo-v2.5-tts", design: "mimo-v2.5-tts-voicedesign", clone: "mimo-v2.5-tts-voiceclone",
} as const;
/** Documented audio-only models, not a name heuristic. */
export const MIMO_NON_CHAT_MODELS: readonly string[] = [...Object.values(MIMO_MODELS), "mimo-v2.5-asr"];
export const MIMO_REFERENCE_ENCODED_LIMIT = 10 * 1024 * 1024;
export type MimoCredentials = { baseUrl: string; apiKey: string };
export type MimoRequestOptions = { fetchImpl?: typeof fetch; signal?: AbortSignal };
export type MimoFailure = {
    ok: false;
    kind: "validation" | "http" | "provider" | "protocol" | "network" | "aborted";
    message: string
};
const fail = (kind: MimoFailure["kind"], message: string): MimoFailure => ({ok: false, kind, message});
const record = (value: unknown): value is Record<string, unknown> => !!value && typeof value === "object" && !Array.isArray(value);
const protocol = () => fail("protocol", "MiMo 未返回完整有效的配音文件；请保留任务记录，不要自动重复生成");

function connection(credentials: MimoCredentials): { base: string; key: string } | undefined {
    const base = normalizeBaseUrl(credentials.baseUrl), key = credentials.apiKey.trim();
    try {
        const url = new URL(base);
        if (!key || !["https:", "http:"].includes(url.protocol) || url.username || url.password || url.search || url.hash || !url.pathname.endsWith("/v1")) return;
        return {base, key};
    } catch {
        return;
    }
}

/** Classify the bounded body without losing observed HTTP failures or reader aborts. */
async function readMimoResponse(response: Response, limit: number, key: string, signal?: AbortSignal): Promise<{ok: true; data: unknown} | MimoFailure> {
    let text: string;
    try {
        text = response.ok
            ? await readResponseText(response, limit, signal)
            : await readErrorText(response, MAX_ERROR_BYTES, signal);
    } catch (error) {
        if (isReadAbort(error, signal)) throw error;
        return error instanceof ResponseLimitError ? fail("protocol", error.message) : protocol();
    }
    let data: unknown;
    try {
        data = JSON.parse(text);
    } catch { /* Preserve HTTP status, otherwise protocol failure. */
    }
    if (!response.ok || (record(data) && data.error != null)) {
        const detail = record(data) && record(data.error) && typeof data.error.message === "string" ? data.error.message : text;
        return fail(response.ok ? "provider" : "http", `MiMo 请求失败${response.ok ? "" : `（${response.status}）`}：${redactCredentials(detail, key).slice(0, 300) || "请检查连接权限、余额和参数"}`);
    }
    return {ok: true, data};
}

async function request(credentials: MimoCredentials, path: "/models" | "/chat/completions", body: unknown | undefined, options: MimoRequestOptions): Promise<{
    ok: true;
    data: unknown
} | MimoFailure> {
    const config = connection(credentials);
    if (!config) return fail("validation", "请配置有效的 MiMo Base URL（以 /v1 结尾）和 API Key");
    if (options.signal?.aborted) return fail("aborted", "请求已停止；远端生成不会因此取消");
    try {
        const response = await (options.fetchImpl ?? fetch)(`${config.base}${path}`, {
            method: body === undefined ? "GET" : "POST",
            headers: {Authorization: `Bearer ${config.key}`, ...(body === undefined ? {} : {"Content-Type": "application/json"})},
            ...(body === undefined ? {} : {body: JSON.stringify(body)}),
            signal: options.signal,
            credentials: "omit",
            redirect: "error",
        });
        return await readMimoResponse(response, path === "/models" ? MAX_JSON_BYTES : MAX_SPEECH_ENVELOPE_BYTES, config.key, options.signal);
    } catch (error) {
        if (isReadAbort(error, options.signal)) return fail("aborted", "请求已停止；远端生成不会因此取消");
        if (error instanceof ResponseLimitError) return protocol();
        const detail = redactCredentials(error instanceof Error ? error.message : "网络错误", config.key).slice(0, 200);
        return fail("network", `MiMo 请求未完成：${detail}；不会自动重复提交`);
    }
}

/** Read-only authentication/model probe, never falls back to paid chat. */
export async function listMimoModels(credentials: MimoCredentials, options: MimoRequestOptions = {}): Promise<ListModelsResult> {
    const result = await request(credentials, "/models", undefined, options);
    if (!result.ok) return result;
    const body = result.data;
    if (!record(body) || !Array.isArray(body.data) || !body.data.every(row => record(row) && typeof row.id === "string" && row.id.trim())) return {
        ok: false,
        message: "MiMo 模型目录响应无效"
    };
    const rows = body.data as Array<Record<string, unknown> & { id: string }>;
    const entries = rows.flatMap(row => {
        const metadata = parseModelMetadata(row);
        return metadata ? [[row.id.trim(), metadata] as const] : [];
    });
    return {
        ok: true,
        models: [...new Set(rows.map(row => row.id.trim()))].sort((a, b) => a.localeCompare(b)), ...(entries.length ? {metadata: collectModelMetadata(entries)} : {})
    };
}

/** Validate actual container bytes, ignoring a misleading declared MIME. Runtime also decodes. */
export async function validateMimoReference(blob: Blob): Promise<"audio/wav" | "audio/mpeg"> {
    if (!blob.size || Math.ceil(blob.size / 3) * 4 > MIMO_REFERENCE_ENCODED_LIMIT) throw new Error("克隆参考音频编码后（含前缀）不能超过 10 MB");
    let mime: string;
    try {
        mime = await detectAudioMime(blob.slice(0, 64, ""));
    } catch {
        throw new Error("克隆参考音频必须是有效的 WAV 或 MP3 文件");
    }
    if (mime !== "audio/wav" && mime !== "audio/mpeg") throw new Error("克隆参考音频仅支持 WAV 或 MP3，请先转换格式");
    if (Math.ceil(blob.size / 3) * 4 + `data:${mime};base64,`.length > MIMO_REFERENCE_ENCODED_LIMIT) throw new Error("克隆参考音频编码后（含前缀）不能超过 10 MB");
    return mime;
}

async function referenceDataUri(blob: Blob): Promise<string> {
    const mime = await validateMimoReference(blob);
    const bytes = new Uint8Array(await blob.arrayBuffer());
    let binary = "";
    for (let start = 0; start < bytes.length; start += 32768) binary += String.fromCharCode(...bytes.subarray(start, start + 32768));
    return `data:${mime};base64,${btoa(binary)}`;
}

export async function generateMimoSpeech(credentials: MimoCredentials, input: {
    text: string;
    voice: string;
    mimo: MimoSpeechSettings;
    referenceBlob?: Blob
}, options: MimoRequestOptions = {}): Promise<{
    ok: true;
    blob: Blob;
    finalTextPreview?: string;
    model: string
} | MimoFailure> {
    const {mimo, text} = input;
    if (!mimo || !Object.hasOwn(MIMO_MODELS, mimo.mode) || typeof mimo.instruction !== "string" || typeof text !== "string") return fail("validation", "MiMo 配音参数无效");
    if (mimo.mode === "design" && !mimo.instruction.trim()) return fail("validation", "请描述要设计的音色");
    if (!text.trim() && !(mimo.mode === "design" && mimo.optimizeTextPreview === true)) return fail("validation", "请输入配音文字");
    if ((mimo.mode !== "design" && mimo.optimizeTextPreview !== undefined) || (mimo.mode !== "clone" && (mimo.referenceMediaId !== undefined || input.referenceBlob !== undefined))) return fail("validation", "音色参数与当前模式不匹配");
    if (mimo.mode === "preset" && !(MIMO_VOICES as readonly string[]).includes(input.voice)) return fail("validation", "请选择 MiMo 预置音色");
    if (mimo.mode === "clone" && (!mimo.referenceMediaId?.trim() || !input.referenceBlob)) return fail("validation", "请选择克隆参考音频");
    const messages = [
        ...(mimo.instruction.trim() ? [{role: "user", content: mimo.instruction}] : []),
        ...(text.trim() ? [{role: "assistant", content: text}] : []),
    ];
    let voice: string | undefined;
    try {
        if (mimo.mode === "clone") voice = await referenceDataUri(input.referenceBlob!);
        else if (mimo.mode === "preset") voice = input.voice;
    } catch (error) {
        return fail("validation", error instanceof Error ? error.message : "克隆参考音频无效");
    }
    const model = MIMO_MODELS[mimo.mode];
    const result = await request(credentials, "/chat/completions", {
        model, messages, stream: false,
        audio: {format: "wav", ...(voice !== undefined ? {voice} : {}), ...(mimo.mode === "design" ? {optimize_text_preview: mimo.optimizeTextPreview ?? false} : {})},
    }, options);
    if (!result.ok) return result;
    const body = result.data;
    const choice = record(body) && Array.isArray(body.choices) ? body.choices[0] : undefined;
    if (!record(choice) || choice.finish_reason !== "stop" || !record(choice.message) || !record(choice.message.audio)) return protocol();
    const message = choice.message, encoded = choice.message.audio.data;
    if (typeof encoded !== "string" || !encoded || encoded.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(encoded)) return protocol();
    let padding = 0;
    if (encoded.endsWith("=")) padding = 1;
    if (encoded.endsWith("==")) padding = 2;
    if (encoded.length / 4 * 3 - padding > MAX_AUDIO_BYTES) return fail("protocol", "MiMo 配音超过本地 32 MiB 音频限制；不会自动重新生成");
    try {
        const decoded = atob(encoded), bytes = Uint8Array.from(decoded, char => char.charCodeAt(0));
        // Validate a WAV container; the runtime performs the complete audio decode after checkpointing.
        const blob = new Blob([bytes], {type: "audio/wav"});
        if (blob.size > MAX_AUDIO_BYTES) return fail("protocol", "MiMo 配音超过本地 32 MiB 音频限制；不会自动重新生成");
        if (await detectAudioMime(blob.slice(0, 64, "")) !== "audio/wav") return protocol();
        const preview = message.final_text_preview;
        if (mimo.optimizeTextPreview && (typeof preview !== "string" || !preview.trim())) return protocol();
        return {
            ok: true,
            blob,
            model, ...(typeof preview === "string" && preview.trim() ? {finalTextPreview: preview} : {})
        };
    } catch {
        return protocol();
    }
}

import {readResponseBlob, readResponseJson, ResponseLimitError} from "./boundedResponse";
import {MAX_MEDIA_DOWNLOAD_BYTES, MAX_JSON_BYTES, MAX_ERROR_BYTES} from "@/lib/resource/limits";
import {redactCredentials} from "./safeError";
import {type ChatModelMetadata, parseModelMetadata} from "@/lib/ai/modelMetadata";

export type AIHubMixCredentials = { baseUrl: string; apiKey: string };
export type AIHubMixRequestOptions = { signal?: AbortSignal; fetchImpl?: typeof fetch };
export type AIHubMixJson = null | boolean | number | string | AIHubMixJson[] | { [key: string]: AIHubMixJson };
export type AIHubMixFailure = {
    ok: false;
    kind: "validation" | "http" | "provider" | "protocol" | "network" | "aborted";
    message: string;
    httpStatus?: number;
    providerCode?: string | number;
    providerType?: string;
    taskId?: string;
};
export type AIHubMixResult<T> = ({ ok: true } & T) | AIHubMixFailure;
export type AIHubMixModel = {
    metadata?: ChatModelMetadata;
    id: string;
    types: string[];
    endpoints: string[];
    inputModalities: string[];
    outputModalities: string[];
    features: string[];
    schemaChecked?: boolean;
    metadataStatus: "available" | "missing" | "invalid";
};
export type AIHubMixMediaKind = "image" | "video";
/** Preserve provider-native parameters; model-specific validation belongs to the provider. */
export type AIHubMixGenerationRequest = {
    model: string;
    prompt: string;
    [key: string]: AIHubMixJson | undefined;
};
export type AIHubMixImageGenerationRequest = AIHubMixGenerationRequest & { async?: boolean; n?: number | null };
export type AIHubMixVideoGenerationRequest = AIHubMixGenerationRequest & { duration?: number | null };
export type AIHubMixOutput = {
    index: number;
    type: "file";
    resultId?: string;
    contentType?: string;
    contentUrl?: string;
    b64Json?: string;
    /** contentUrl is a protected API route, never a public preview URL. */
    requiresAuthentication: true;
};
export type AIHubMixTask = {
    id: string;
    kind: AIHubMixMediaKind;
    model: string;
    status: "queued" | "running" | "completed" | "failed" | "cancelled" | "unknown";
    providerStatus: string;
    outputs: AIHubMixOutput[];
    createdAt?: number | null;
    completedAt?: number | null;
    expiresAt?: number | null;
    error?: { code?: string | number; message?: string; type?: string; upstreamDetail?: AIHubMixJson };
};
export type AIHubMixModelSchema = {
    status: "available" | "missing" | "invalid";
    path: string;
    schema?: { [key: string]: AIHubMixJson } | boolean;
};
const PATHS = {image: "/ai/v1/images/generations", video: "/ai/v1/videos"} as const;
const TYPE_ALIASES: Record<string, string> = {t2t: "llm", t2i: "image_generation", t2v: "video", reranking: "rerank"};

function record(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonempty(value: unknown): value is string {
    return typeof value === "string" && value.trim().length > 0;
}

function finite(value: unknown): value is number {
    return typeof value === "number" && Number.isFinite(value);
}

function jsonValue(value: unknown): value is AIHubMixJson {
    if (value === null || typeof value === "string" || typeof value === "boolean") return true;
    if (typeof value === "number") return Number.isFinite(value);
    if (Array.isArray(value)) return value.every(jsonValue);
    return record(value) && Object.getPrototypeOf(value) === Object.prototype && Object.values(value).every(jsonValue);
}

function redact(value: string, key: string): string {
    return redactCredentials(value, key).slice(0, 500);
}

function sanitizedJson(value: AIHubMixJson, key: string): AIHubMixJson {
    if (typeof value === "string") return redact(value, key);
    if (Array.isArray(value)) return value.map((item) => sanitizedJson(item, key));
    if (record(value)) return Object.fromEntries(Object.entries(value).map(([name, item]) => [redact(name, key), sanitizedJson(item, key)]));
    return value;
}

function failure(kind: AIHubMixFailure["kind"], message: string): AIHubMixFailure {
    return {ok: false, kind, message};
}

function protocol(taskId?: string): AIHubMixFailure {
    return {...failure("protocol", "AIHubMix 返回的数据格式不符合接口约定"), ...(taskId ? {taskId} : {})};
}

function aborted(): AIHubMixFailure {
    return failure("aborted", "请求已中止；已提交的远端任务不会因此取消");
}

function isAbort(error: unknown, options: AIHubMixRequestOptions) {
    return options.signal?.aborted || (error instanceof Error && error.name === "AbortError");
}

function providerRoot(baseUrl: string): string | undefined {
    try {
        const base = baseUrl.trim().replace(/\/+$/, "");
        const url = new URL(base);
        if (!/^https?:$/.test(url.protocol) || url.username || url.password || url.search || url.hash ||
            !url.pathname.endsWith("/v1") || /\\|%(?:2f|5c)/i.test(base)) return undefined;
        return `${url.origin}${url.pathname.slice(0, -3)}`;
    } catch {
        return undefined;
    }
}

function segment(value: unknown): value is string {
    return nonempty(value) && value === value.trim() && value !== "." && value !== ".." && !/[\\/?#%]/.test(value);
}

function taskError(value: unknown, key: string): AIHubMixTask["error"] {
    if (!record(value)) return undefined;
    return {
        code: typeof value.code === "string" ? redact(value.code, key) : finite(value.code) ? value.code : undefined,
        message: typeof value.message === "string" ? redact(value.message, key) : undefined,
        type: typeof value.type === "string" ? redact(value.type, key) : undefined,
        upstreamDetail: value.upstream_detail !== undefined && jsonValue(value.upstream_detail) ? sanitizedJson(value.upstream_detail, key) : undefined,
    };
}

function responseFailure(response: Response, body: unknown, key: string): AIHubMixFailure {
    const envelope = record(body) ? body : undefined;
    const error = taskError(envelope?.error, key);
    const detail = error?.message ?? (typeof envelope?.message === "string" ? redact(envelope.message, key) : undefined);
    return {
        ok: false, kind: response.ok ? "provider" : "http", httpStatus: response.status,
        message: `AIHubMix 请求失败（${response.status}）${detail ? `：${detail}` : ""}`,
        providerCode: error?.code, providerType: error?.type,
        ...(nonempty(envelope?.id) ? {taskId: redact(envelope.id, key)} : {}),
    };
}

async function transport(
    credentials: AIHubMixCredentials, path: string,
    options: AIHubMixRequestOptions, authenticated: boolean, body?: string,
): Promise<AIHubMixResult<{ response: Response }>> {
    const root = providerRoot(credentials.baseUrl);
    if (!root) return failure("validation", "Base URL 必须是以 /v1 结尾的 HTTP(S) 地址，且不包含账号、查询参数或片段");
    if (authenticated && !credentials.apiKey.trim()) return failure("validation", "请填写 API Key");
    if (options.signal?.aborted) return aborted();
    try {
        const response = await (options.fetchImpl ?? fetch)(`${root}${path}`, {
            method: body === undefined ? "GET" : "POST",
            headers: {
                ...(authenticated ? {Authorization: `Bearer ${credentials.apiKey.trim()}`} : {}),
                ...(body !== undefined ? {"Content-Type": "application/json"} : {}),
            },
            ...(body === undefined ? {} : {body}),
            signal: options.signal, redirect: "error", credentials: "omit",
        });
        if (options.signal?.aborted) return aborted();
        return {ok: true, response};
    } catch (error) {
        return isAbort(error, options) ? aborted() : failure("network", "无法连接 AIHubMix，请检查网络、Base URL 和浏览器跨域限制；提交结果可能尚未确认");
    }
}

async function request(
    credentials: AIHubMixCredentials, path: string, options: AIHubMixRequestOptions,
    authenticated: boolean, body?: string, taskResponse = false,
): Promise<AIHubMixResult<{ data: Record<string, unknown> }>> {
    const result = await transport(credentials, path, options, authenticated, body);
    if (!result.ok) return result;
    const {response} = result;
    let data: unknown;
    try {
        data = await response.json();
    } catch (error) {
        if (isAbort(error, options)) return aborted();
        return response.ok ? protocol() : responseFailure(response, undefined, credentials.apiKey);
    }
    if (options.signal?.aborted) return aborted();
    // Failed task reads are successful reads; only request error envelopes are failures.
    const isTask = taskResponse && record(data) && (data.object === "image" || data.object === "video") && nonempty(data.id);
    if (!response.ok || (record(data) && (data.success === false || (!isTask && data.error != null)))) {
        return responseFailure(response, data, credentials.apiKey);
    }
    return record(data) ? {ok: true, data} : protocol();
}

function tokens(value: unknown): string[] | undefined {
    if (value == null) return [];
    if (typeof value === "string") return [...new Set(value.split(",").map((item) => item.trim().toLowerCase()).filter(Boolean))];
    if (Array.isArray(value) && value.every((item) => typeof item === "string")) return [...new Set(value.flatMap((item) => tokens(item) ?? []))];
    return undefined;
}

/** Public directory; success is never evidence that the configured key is valid. */
export async function listAIHubMixModels(credentials: AIHubMixCredentials, options: AIHubMixRequestOptions = {}): Promise<AIHubMixResult<{
    models: AIHubMixModel[]
}>> {
    const result = await request(credentials, "/api/v1/models", options, false);
    if (!result.ok) return result;
    if (result.data.success !== true || !Array.isArray(result.data.data)) return protocol();
    const models: AIHubMixModel[] = [];
    for (const row of result.data.data) {
        if (!record(row) || !nonempty(row.model_id)) return protocol();
        const types = tokens(row.types), endpoints = tokens(row.endpoints), input = tokens(row.input_modalities),
            output = tokens(row.output_modalities), features = tokens(row.features);
        const invalid = [types, endpoints, input, output, features].some((value) => value === undefined) || (row.schema_checked != null && typeof row.schema_checked !== "boolean");
        models.push({
            ...(parseModelMetadata(row) ? {metadata: parseModelMetadata(row)} : {}),
            id: row.model_id.trim(),
            types: [...new Set((types ?? []).map((type) => Object.hasOwn(TYPE_ALIASES, type) ? TYPE_ALIASES[type]! : type))],
            endpoints: endpoints ?? [],
            inputModalities: input ?? [],
            outputModalities: output ?? [],
            features: features ?? [],
            schemaChecked: typeof row.schema_checked === "boolean" ? row.schema_checked : undefined,
            metadataStatus: invalid ? "invalid" : types?.length ? "available" : "missing",
        });
    }
    return {ok: true, models};
}

/** Authenticated read only; proves access to task listing, not every model entitlement. */
export async function testAIHubMixConnection(credentials: AIHubMixCredentials, options: AIHubMixRequestOptions = {}): Promise<AIHubMixResult<Record<never, never>>> {
    const result = await request(credentials, "/ai/v1/images?limit=1", options, true);
    if (!result.ok) return result;
    const data = result.data;
    if (data.object !== "list" || !Array.isArray(data.data) || typeof data.has_more !== "boolean" ||
        !(data.next_after === null || typeof data.next_after === "string") ||
        !data.data.every((row) => record(row) && nonempty(row.id) && row.object === "image")) return protocol();
    return {ok: true};
}

function validSchema(value: unknown): value is NonNullable<AIHubMixModelSchema["schema"]> {
    if (typeof value === "boolean") return true;
    return record(value) && jsonValue(value) &&
        (value.properties === undefined || record(value.properties)) &&
        (value.required === undefined || (Array.isArray(value.required) && value.required.every(nonempty))) &&
        (value.type === undefined || nonempty(value.type) || (Array.isArray(value.type) && value.type.every(nonempty)));
}

export async function getAIHubMixModelSchema(credentials: AIHubMixCredentials, model: string, kind: AIHubMixMediaKind, options: AIHubMixRequestOptions = {}): Promise<AIHubMixResult<AIHubMixModelSchema>> {
    if (!nonempty(model) || model === "." || model === ".." || !Object.hasOwn(PATHS, kind)) return failure("validation", "请提供有效的模型和媒体类型");
    const result = await request(credentials, `/call/schema/models/${encodeURIComponent(model)}/endpoints`, options, false);
    if (!result.ok) return result;
    const path = PATHS[kind];
    if (!Array.isArray(result.data.endpoints) || result.data.modality !== kind || !result.data.endpoints.every(record)) return {
        ok: true,
        path,
        status: "invalid"
    };
    const candidates = result.data.endpoints.filter((row) => row.path === path && row.method === "POST");
    if (!candidates.length) return {ok: true, path, status: "missing"};
    if (candidates.length !== 1) return {ok: true, path, status: "invalid"};
    const candidate = candidates[0]!;
    const schema = record(candidate.request) ? candidate.request.schema : undefined;
    return validSchema(schema) ? {ok: true, path, status: "available", schema} : {ok: true, path, status: "invalid"};
}

function parseTask(data: Record<string, unknown>, kind: AIHubMixMediaKind, key: string, expectedId?: string): AIHubMixResult<{
    task: AIHubMixTask
}> {
    const id = nonempty(data.id) ? redact(data.id, key) : undefined;
    if (!segment(data.id) || data.object !== kind || (expectedId !== undefined && data.id !== expectedId) || !nonempty(data.model) || !Array.isArray(data.output)) return protocol(id);
    if (data.status !== undefined && !nonempty(data.status)) return protocol(id);
    if ([data.created_at, data.completed_at, data.expires_at].some((value) => value !== undefined && value !== null && (!finite(value) || !Number.isInteger(value)))) return protocol(id);
    if (data.error != null && !record(data.error)) return protocol(id);
    const outputs: AIHubMixOutput[] = [];
    for (const item of data.output) {
        if (!record(item) || !finite(item.index) || !Number.isInteger(item.index) || item.index < 0 || item.type !== "file" || outputs.some((output) => output.index === item.index)) return protocol(id);
        if ([item.content_url, item.b64_json, item.content_type, item.result_id].some((value) => value != null && !nonempty(value))) return protocol(id);
        if (!nonempty(item.content_url) && !nonempty(item.b64_json)) return protocol(id);
        outputs.push({
            index: item.index, type: "file", requiresAuthentication: true,
            contentUrl: nonempty(item.content_url) ? item.content_url : undefined,
            b64Json: nonempty(item.b64_json) ? item.b64_json : undefined,
            contentType: nonempty(item.content_type) ? item.content_type : undefined,
            resultId: nonempty(item.result_id) ? item.result_id : undefined,
        });
    }
    if (data.status === "completed" && !outputs.length) return protocol(id);
    const providerStatus = typeof data.status === "string" ? data.status : "";
    const statuses: Record<string, AIHubMixTask["status"]> = {
        pending: "queued",
        in_progress: "running",
        completed: "completed",
        failed: "failed",
        cancelled: "cancelled"
    };
    const timestamp = (value: unknown) => value === null ? null : finite(value) ? value : undefined;
    return {
        ok: true, task: {
            id: data.id,
            kind,
            model: data.model,
            status: Object.hasOwn(statuses, providerStatus) ? statuses[providerStatus]! : "unknown",
            providerStatus,
            outputs,
            createdAt: timestamp(data.created_at),
            completedAt: timestamp(data.completed_at),
            expiresAt: timestamp(data.expires_at),
            error: taskError(data.error, key),
        }
    };
}

async function submit(credentials: AIHubMixCredentials, input: AIHubMixGenerationRequest, kind: AIHubMixMediaKind, options: AIHubMixRequestOptions): Promise<AIHubMixResult<{
    task: AIHubMixTask
}>> {
    if (!record(input) || !nonempty(input.model) || !nonempty(input.prompt)) return failure("validation", "请填写生成模型和提示词");
    if (kind === "image" && input.async !== undefined && typeof input.async !== "boolean") return failure("validation", "async 必须是布尔值");
    if (kind === "video" && input.duration != null && (!finite(input.duration) || !Number.isInteger(input.duration) || input.duration <= 0)) return failure("validation", "视频时长必须是正整数");
    let body: string;
    try {
        if (!Object.values(input).every((value) => value === undefined || jsonValue(value))) return failure("validation", "生成参数必须是有效的 JSON");
        body = JSON.stringify(input);
    } catch {
        return failure("validation", "生成参数必须是有效的 JSON");
    }
    const result = await request(credentials, PATHS[kind], options, true, body, true);
    return result.ok ? parseTask(result.data, kind, credentials.apiKey) : result;
}

export function submitAIHubMixImageGeneration(credentials: AIHubMixCredentials, input: AIHubMixImageGenerationRequest, options: AIHubMixRequestOptions = {}) {
    return submit(credentials, input, "image", options);
}

export function submitAIHubMixVideoGeneration(credentials: AIHubMixCredentials, input: AIHubMixVideoGenerationRequest, options: AIHubMixRequestOptions = {}) {
    return submit(credentials, input, "video", options);
}

async function getTask(credentials: AIHubMixCredentials, taskId: string, kind: AIHubMixMediaKind, options: AIHubMixRequestOptions): Promise<AIHubMixResult<{
    task: AIHubMixTask
}>> {
    if (!segment(taskId)) return failure("validation", "请提供有效的任务 ID");
    const result = await request(credentials, `/ai/v1/${kind}s/${encodeURIComponent(taskId)}`, options, true, undefined, true);
    return result.ok ? parseTask(result.data, kind, credentials.apiKey, taskId) : result;
}

export function getAIHubMixImageTask(credentials: AIHubMixCredentials, taskId: string, options: AIHubMixRequestOptions = {}) {
    return getTask(credentials, taskId, "image", options);
}

export function getAIHubMixVideoTask(credentials: AIHubMixCredentials, taskId: string, options: AIHubMixRequestOptions = {}) {
    return getTask(credentials, taskId, "video", options);
}

/** Explicit protected binary read. Never follows redirects or writes to local media storage. */
export async function downloadAIHubMixResult(credentials: AIHubMixCredentials, task: AIHubMixTask, output: AIHubMixOutput, options: AIHubMixRequestOptions = {}): Promise<AIHubMixResult<{
    blob: Blob
}>> {
    if (options.signal?.aborted) return aborted();
    if (task.status !== "completed") return {
        ...failure("validation", "任务结果尚未就绪"),
        providerCode: "result_not_ready"
    };
    const root = providerRoot(credentials.baseUrl);
    if (!root || !segment(task.id) || !["image", "video"].includes(task.kind) || !nonempty(output.contentUrl) ||
        !task.outputs.some((item) => item.index === output.index && item.contentUrl === output.contentUrl)) return failure("validation", "请提供该任务的有效下载地址");
    let path: string;
    try {
        const url = new URL(output.contentUrl, `${root}/`);
        const expected = new URL(`${root}/ai/v1/${task.kind}s/${encodeURIComponent(task.id)}/content`);
        const tail = url.pathname.slice(expected.pathname.length + 1);
        if (url.origin !== expected.origin || url.username || url.password || url.search || url.hash ||
            (task.kind === "video" ? url.pathname !== expected.pathname : !url.pathname.startsWith(`${expected.pathname}/`) || !segment(decodeURIComponent(tail)))) throw new Error("invalid content route");
        path = url.pathname.slice(new URL(root).pathname.replace(/\/$/, "").length);
    } catch {
        return failure("validation", "下载地址必须属于当前供应商及当前任务的结果接口");
    }
    const result = await transport(credentials, path, options, true);
    if (!result.ok) return result;
    try {
        if (!result.response.ok || result.response.headers.get("Content-Type")?.includes("application/json")) {
            let body: unknown;
            try {
                body = await readResponseJson(result.response, result.response.ok ? MAX_JSON_BYTES : MAX_ERROR_BYTES, options.signal);
            } catch (error) {
                if (isAbort(error, options)) return aborted();
            }
            return result.response.ok && !(record(body) && body.error != null) ? protocol(task.id) : responseFailure(result.response, body, credentials.apiKey);
        }
        const blob = await readResponseBlob(result.response, MAX_MEDIA_DOWNLOAD_BYTES, options.signal);
        if (options.signal?.aborted) return aborted();
        return blob.size > 0 ? {ok: true, blob} : protocol(task.id);
    } catch (error) {
        if (isAbort(error, options)) return aborted();
        if (error instanceof ResponseLimitError) return failure("protocol", "AIHubMix 图片/视频下载超过本地 256 MiB 限制，已停止读取；保留任务记录，不会重新生成");
        return failure("network", "AIHubMix 结果读取失败，请检查网络和浏览器跨域限制");
    }
}

import {appendedUtf8Bytes, assertResponseBytes, isReadAbort, readErrorText, readResponseJson, utf8Bytes} from "./boundedResponse";
import {readSseEvents} from "./boundedSse";
import {MAX_JSON_BYTES, MAX_ERROR_BYTES} from "@/lib/resource/limits";
import {redactCredentials} from "./safeError";
import {materializeChatMessages} from "./referenceWire";
import type {AgentVisionCapability} from "@/domain/referenceInput";
import {authHeaders, chatCompletionsUrl, normalizeBaseUrl,} from "@/lib/ai/openaiCompatible";

import {assertReasoningEffort} from "@/lib/ai/reasoningPolicy";
import type {ConnectorDefinitionId} from "@/domain/types";
import type {
    AgentModelMetrics,
    AgentReasoningEffort,
    AgentRequestMessage,
    AgentTokenUsage,
    AgentToolSchema,
    AgentWireToolCall
} from "@/domain/agent";

export type ChatCompletionMessage = AgentRequestMessage;

export type StreamChatInput = {
    projectId?: string;
    runId?: string;
    visionCapability?: AgentVisionCapability;
    maxOutputTokens?: number;
    baseUrl: string;
    apiKey: string;
    model: string;
    connectorDefinitionId?: ConnectorDefinitionId;
    reasoningEffort?: AgentReasoningEffort;
    messages: ChatCompletionMessage[];
    tools?: AgentToolSchema[];
};

/** One SSE/JSON chunk may carry answer text, reasoning text, or both. */
export type StreamDelta = {
    content?: string;
    reasoning?: string;
};

export type StreamChatHandlers = {
    onDelta?: (text: string) => void;
    onReasoning?: (text: string) => void;
    signal?: AbortSignal;
    fetchImpl?: typeof fetch;
};

export type StreamChatResult = ({ metrics?: Omit<AgentModelMetrics, "step">; usage?: AgentTokenUsage }) & (
    | {
    ok: true;
    content: string;
    reasoning: string;
    via: "stream" | "json";
    finishReason?: string;
    toolCalls?: AgentWireToolCall[]
}
    | { ok: false; message: string; aborted?: boolean; finishReason?: string });

/**
 * Accumulate reasoning/content deltas and close reasoning on first answer token
 * (LobeHub lifecycle without an operation store).
 */
export type ReasoningAccum = {
    content: string;
    reasoning: string;
    reasoningActive: boolean;
    reasoningStartedAt: number | null;
    reasoningDurationMs?: number;
};

export function createReasoningAccum(): ReasoningAccum {
    return {
        content: "",
        reasoning: "",
        reasoningActive: false,
        reasoningStartedAt: null,
    };
}

export function accumulateStreamDelta(
    state: ReasoningAccum,
    delta: StreamDelta,
    nowMs: number,
): ReasoningAccum {
    let content = state.content;
    let reasoning = state.reasoning;
    let reasoningActive = state.reasoningActive;
    let reasoningStartedAt = state.reasoningStartedAt;
    let reasoningDurationMs = state.reasoningDurationMs;

    if (delta.reasoning) {
        if (reasoningStartedAt == null) {
            reasoningStartedAt = nowMs;
        }
        reasoning += delta.reasoning;
        if (!content) reasoningActive = true;
    }

    if (delta.content) {
        if (reasoningActive && reasoningStartedAt != null && reasoningDurationMs == null) {
            reasoningDurationMs = Math.max(0, nowMs - reasoningStartedAt);
            reasoningActive = false;
        }
        content += delta.content;
    }

    return {
        content,
        reasoning,
        reasoningActive,
        reasoningStartedAt,
        reasoningDurationMs,
    };
}

/** End reasoning on abort/complete so the panel can collapse. */
export function finalizeReasoningAccum(
    state: ReasoningAccum,
    nowMs: number,
): ReasoningAccum {
    if (!state.reasoningActive) return state;
    const started = state.reasoningStartedAt;
    return {
        ...state,
        reasoningActive: false,
        reasoningDurationMs:
            state.reasoningDurationMs ??
            (started != null ? Math.max(0, nowMs - started) : undefined),
    };
}

function pickReasoningText(source: {
    reasoning_content?: unknown;
    reasoning?: unknown
} | undefined): string | undefined {
    if (!source) return undefined;
    if (typeof source.reasoning_content === "string" && source.reasoning_content.length > 0) {
        return source.reasoning_content;
    }
    if (typeof source.reasoning === "string" && source.reasoning.length > 0) {
        return source.reasoning;
    }
    return undefined;
}

function pickContentText(source: { content?: unknown } | undefined): string | undefined {
    if (typeof source?.content === "string" && source.content.length > 0) {
        return source.content;
    }
    return undefined;
}

function formatHttpError(status: number, body: string): string {
    const trimmed = body.trim().slice(0, 200);
    if (status === 401 || status === 403) {
        return trimmed ? `鉴权失败（${status}）：${trimmed}` : `鉴权失败（${status}）`;
    }
    return trimmed ? `请求失败（${status}）：${trimmed}` : `请求失败（${status}）`;
}

function record(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function redactError(message: string, apiKey: string): string {
    return redactCredentials(message, apiKey).slice(0, 300);
}

function streamErrorMessage(data: string): string {
    try {
        const value: unknown = JSON.parse(data);
        if (record(value)) {
            const error = record(value.error) ? value.error : value;
            if (typeof error.message === "string") return error.message;
        }
    } catch { /* Providers may use plain-text error events. */ }
    return data || "模型服务返回错误";
}

function readUsage(data: unknown): AgentTokenUsage | undefined {
    if (!record(data) || !record(data.usage)) return undefined;
    const usage: AgentTokenUsage = {};
    for (const [wire, name] of [["prompt_tokens", "inputTokens"], ["completion_tokens", "outputTokens"], ["total_tokens", "totalTokens"]] as const) {
        const value = data.usage[wire];
        if (typeof value === "number" && Number.isSafeInteger(value) && value >= 0) usage[name] = value;
    }
    const details = data.usage.prompt_tokens_details;
    const cached = record(details) ? details.cached_tokens : undefined;
    if (typeof cached === "number" && Number.isSafeInteger(cached) && cached >= 0 && (usage.inputTokens === undefined || cached <= usage.inputTokens)) usage.cachedInputTokens = cached;
    return Object.keys(usage).length ? usage : undefined;
}

function decodeCompletion(data: unknown, stream: boolean): {
    delta: StreamDelta;
    finishReason?: string;
    toolFragments?: unknown[];
} {
    if (!record(data)) throw new Error("模型返回了无效的响应格式");
    if (data.error != null) {
        const error = data.error;
        throw new Error(record(error) && typeof error.message === "string"
            ? error.message : typeof error === "string" ? error : "模型服务返回错误");
    }
    if (!Array.isArray(data.choices)) throw new Error("模型响应缺少 choices");
    if (stream && data.choices.length === 0 && record(data.usage)) return {delta: {}};
    const choice = data.choices[0];
    if (!record(choice)) throw new Error("模型响应缺少有效的回复");
    const source = stream ? (choice.delta ?? choice.message) : choice.message;
    if (!record(source)) throw new Error("模型回复格式无效");
    for (const name of ["content", "reasoning_content", "reasoning"]) {
        if (source[name] != null && typeof source[name] !== "string") {
            throw new Error("当前聊天仅支持文本回复");
        }
    }
    if (source.function_call != null) {
        throw new Error("模型请求了工具调用，当前执行尚未启用工具能力");
    }
    if (source.tool_calls != null && !Array.isArray(source.tool_calls)) throw new Error("工具调用格式无效");
    const finishReason = choice.finish_reason;
    if (finishReason != null && (typeof finishReason !== "string" || !finishReason)) {
        throw new Error("模型返回了无效的结束状态");
    }
    return {
        ...(Array.isArray(source.tool_calls) ? {toolFragments: source.tool_calls} : {}),
        delta: {
            ...(pickContentText(source) ? {content: pickContentText(source)} : {}),
            ...(pickReasoningText(source) ? {reasoning: pickReasoningText(source)} : {}),
        },
        ...(typeof finishReason === "string" ? {finishReason} : {}),
    };
}

/** Assemble bounded provider fragments; execution still validates strict tool arguments. */
function createToolAccumulator(tools?: AgentToolSchema[]) {
    const calls = new Map<number, { id: string; name: string; arguments: string }>();
    let retainedBytes = 0;
    const callBytes = (call: {id: string; name: string; arguments: string}) => utf8Bytes(call.id) + utf8Bytes(call.name) + utf8Bytes(call.arguments);
    return {
        push(fragments: unknown[] | undefined, streaming: boolean) {
            if (!fragments?.length) return;
            if (!tools?.length) throw new Error("模型请求了工具调用，当前执行尚未启用工具能力");
            for (const [position, fragment] of fragments.entries()) {
                if (!record(fragment)) throw new Error("工具调用格式无效");
                const index = streaming ? fragment.index : position;
                if (typeof index !== "number" || !Number.isInteger(index) || index < 0 || index >= 16) throw new Error("工具调用索引无效或超过限制");
                const call = {...(calls.get(index) ?? {id: "", name: "", arguments: ""})};
                const beforeBytes = callBytes(call);
                if (fragment.type != null && fragment.type !== "function") throw new Error("不支持的工具调用类型");
                if (fragment.id != null) {
                    if (typeof fragment.id !== "string" || (call.id && call.id !== fragment.id)) throw new Error("工具调用标识冲突");
                    call.id = fragment.id;
                }
                if (fragment.function != null) {
                    if (!record(fragment.function)) throw new Error("工具调用函数格式无效");
                    for (const field of ["name", "arguments"] as const) {
                        const value = fragment.function[field];
                        if (value != null && typeof value !== "string") throw new Error("工具调用参数格式无效");
                        if (typeof value === "string") call[field] += value;
                    }
                }
                if (call.arguments.length > 32768 || call.name.length > 128 || call.id.length > 256) throw new Error("工具调用超过大小限制");
                retainedBytes += callBytes(call) - beforeBytes;
                calls.set(index, call);
            }
        },
        retainedBytes(): number {
            return retainedBytes;
        },
        finish(): AgentWireToolCall[] | undefined {
            if (!calls.size) return undefined;
            const seen = new Set<string>();
            return [...calls.entries()].sort(([a], [b]) => a - b).map(([index, call], position) => {
                if (index !== position || !call.id || seen.has(call.id) || !tools?.some((tool) => tool.function.name === call.name)) throw new Error("工具调用缺少标识、重复或请求了未启用的工具");
                seen.add(call.id);
                let args: unknown;
                try {
                    args = JSON.parse(call.arguments);
                } catch {
                    throw new Error("工具调用参数不是完整 JSON");
                }
                if (!record(args)) throw new Error("工具参数必须是对象");
                return {id: call.id, type: "function", function: {name: call.name, arguments: call.arguments}};
            });
        },
    };
}

function completionResult(
    content: string,
    reasoning: string,
    via: "stream" | "json",
    finishReason?: string,
    toolCalls?: AgentWireToolCall[],
): StreamChatResult {
    const metadata = finishReason ? {finishReason} : {};
    if (toolCalls?.length) {
        if (finishReason !== "tool_calls") return {ok: false, message: "工具调用缺少完整结束状态", ...metadata};
        return {ok: true, content, reasoning, via, toolCalls, ...metadata};
    }
    if (finishReason && finishReason !== "stop") {
        const message = finishReason === "length" ? "回复达到模型长度上限，内容未完成"
            : finishReason === "content_filter" ? "回复被模型内容过滤中断"
                : finishReason === "tool_calls" || finishReason === "function_call"
                    ? "模型请求了工具调用，当前执行尚未启用工具能力"
                    : "模型返回了未支持的结束状态";
        return {ok: false, message, ...metadata};
    }
    if (!content.trim()) return {ok: false, message: "模型未返回有效的回答内容", ...metadata};
    return {ok: true, content, reasoning, via, ...metadata};
}

function applyDeltaHandlers(
    handlers: StreamChatHandlers,
    delta: StreamDelta,
    acc: { content: string; reasoning: string },
): void {
    handlers.signal?.throwIfAborted();
    if (delta.reasoning) {
        acc.reasoning += delta.reasoning;
        handlers.onReasoning?.(delta.reasoning);
    }
    handlers.signal?.throwIfAborted();
    if (delta.content) {
        acc.content += delta.content;
        handlers.onDelta?.(delta.content);
    }
}

/** One POST per attempt. A JSON response to that same request is supported. */
export async function streamChatCompletions(
    input: StreamChatInput,
    handlers: StreamChatHandlers = {},
): Promise<StreamChatResult> {
    const base = normalizeBaseUrl(input.baseUrl);
    const apiKey = input.apiKey.trim();
    const model = input.model.trim();
    if (!base) return {ok: false, message: "请填写 Base URL"};
    if (!apiKey) return {ok: false, message: "请填写 API Key"};
    if (!model) return {ok: false, message: "请选择模型"};
    if (input.messages.length === 0) return {ok: false, message: "消息不能为空"};

    const fetchImpl = handlers.fetchImpl ?? fetch;
    const signal = handlers.signal;
    const startedAt = Date.now();
    let firstTokenAt: number | undefined;
    let usage: AgentTokenUsage | undefined;
    const observe = (delta: StreamDelta, tools?: unknown[]) => {
        if (firstTokenAt === undefined && (delta.content || delta.reasoning || tools?.length)) firstTokenAt = Date.now();
    };
    const withMetrics = (result: StreamChatResult): StreamChatResult => ({
        ...result, ...(usage ? {usage} : {}),
        metrics: {
            startedAt, ...(firstTokenAt !== undefined ? {firstTokenAt} : {}),
            endedAt: Date.now(), ...(usage ? {usage} : {})
        },
    });

    try {
        signal?.throwIfAborted();
        assertReasoningEffort(input.connectorDefinitionId ? {
            definitionId: input.connectorDefinitionId,
            baseUrl: base
        } : undefined, model, input.reasoningEffort);
        const res = await fetchImpl(chatCompletionsUrl(base), {
            method: "POST",
            headers: authHeaders(apiKey),
            signal,
            body: JSON.stringify({
                model, ...(input.maxOutputTokens ? (/^(gpt-|o[1-9])/.test(model) ? {max_completion_tokens: input.maxOutputTokens} : {max_tokens: input.maxOutputTokens}) : {}),
                messages: await materializeChatMessages(input.messages, input, signal),
                stream: true, ...(input.reasoningEffort !== undefined ? {reasoning_effort: input.reasoningEffort} : {}), ...(input.tools?.length ? {tools: input.tools} : {})
            }),
        });
        signal?.throwIfAborted();
        if (!res.ok) {
            const body = await readErrorText(res, MAX_ERROR_BYTES, signal);
            signal?.throwIfAborted();
            return withMetrics({ok: false, message: formatHttpError(res.status, redactError(body, apiKey))});
        }

        const contentType = res.headers.get("content-type") ?? "";
        if (!contentType.toLowerCase().includes("text/event-stream")) {
            const data = await readResponseJson(res, MAX_JSON_BYTES, signal);
            signal?.throwIfAborted();
            usage = readUsage(data);
            const {delta, finishReason, toolFragments} = decodeCompletion(data, false);
            const calls = createToolAccumulator(input.tools);
            calls.push(toolFragments, false);
            const acc = {content: "", reasoning: ""};
            assertResponseBytes(utf8Bytes(delta.content ?? "") + utf8Bytes(delta.reasoning ?? "") + calls.retainedBytes(), MAX_JSON_BYTES);
            applyDeltaHandlers(handlers, delta, acc);
            signal?.throwIfAborted();
            return withMetrics(completionResult(acc.content, acc.reasoning, "json", finishReason ? redactError(finishReason, apiKey) : undefined, calls.finish()));
        }
        if (!res.body) throw new Error("模型返回了空的响应流");

        const calls = createToolAccumulator(input.tools);
        let completed = false;
        let finishReason: string | undefined;
        let outputBytes = 0;
        const acc = {content: "", reasoning: ""};
        const dispatchEvent = (data: string, type: string) => {
            if (!data && type !== "error") return;
            if (type === "error") throw new Error(streamErrorMessage(data));
            if (data.trim() === "[DONE]") {
                completed = true;
                return;
            }
            let value: unknown;
            try {
                value = JSON.parse(data);
            } catch {
                throw new Error("模型返回了无效的流事件");
            }
            usage = readUsage(value) ?? usage;
            const frame = decodeCompletion(value, true);
            observe(frame.delta, frame.toolFragments);
            if (finishReason && (frame.delta.content || frame.delta.reasoning || frame.finishReason || frame.toolFragments?.length)) {
                throw new Error("模型在结束状态后继续返回内容");
            }
            calls.push(frame.toolFragments, true);
            const nextBytes = outputBytes + appendedUtf8Bytes(acc.content, frame.delta.content ?? "") + appendedUtf8Bytes(acc.reasoning, frame.delta.reasoning ?? "");
            assertResponseBytes(nextBytes + calls.retainedBytes(), MAX_JSON_BYTES);
            outputBytes = nextBytes;
            applyDeltaHandlers(handlers, frame.delta, acc);
            if (frame.finishReason) finishReason = redactError(frame.finishReason, apiKey);
        };
        for await (const event of readSseEvents(res, signal)) {
            dispatchEvent(event.data, event.event);
            if (completed) break;
        }
        signal?.throwIfAborted();
        if (!completed && !finishReason) throw new Error("回复流意外中断，已保留收到的内容");
        return withMetrics(completionResult(acc.content, acc.reasoning, "stream", finishReason, calls.finish()));
    } catch (err) {
        if (isReadAbort(err, signal)) {
            return withMetrics({ok: false, message: "已停止", aborted: true});
        }
        return withMetrics({ok: false, message: redactError(err instanceof Error ? err.message : "网络错误", apiKey)});
    }
}

import {appendedUtf8Bytes, assertResponseBytes, isReadAbort, readErrorText, readResponseJson, utf8Bytes} from "./boundedResponse";
import {readSseEvents} from "./boundedSse";
import {MAX_JSON_BYTES, MAX_ERROR_BYTES} from "@/lib/resource/limits";
import {redactCredentials} from "./safeError";
import {materializeResponseItems} from "./referenceWire";
import type {AgentRequestMessage, AgentResponseItem, AgentTokenUsage, AgentWireToolCall} from "@/domain/agent";
import type {StreamChatHandlers, StreamChatInput, StreamChatResult} from "@/lib/ai/chatStream";
import {authHeaders, normalizeBaseUrl} from "@/lib/ai/openaiCompatible";
import {assertReasoningEffort} from "@/lib/ai/reasoningPolicy";

export type ResponsesResult = StreamChatResult & { responseOutput?: AgentResponseItem[] };
const MAX_ENVELOPE_SIZE = MAX_JSON_BYTES;
const RESPONSE_STATUSES = new Set(["completed", "failed", "incomplete", "in_progress", "queued", "cancelled"]);

function record(value: unknown): value is Record<string, unknown> {
    return !!value && typeof value === "object" && !Array.isArray(value);
}

function text(value: unknown, max = MAX_ENVELOPE_SIZE): string {
    if (typeof value !== "string" || value.length > max) throw new Error("Responses 返回了无效或过大的字段");
    return value;
}

function id(value: unknown): string {
    const result = text(value, 256);
    if (!result) throw new Error("Responses 缺少调用标识");
    return result;
}

function usageOf(value: unknown): AgentTokenUsage | undefined {
    if (!record(value)) return;
    const usage: AgentTokenUsage = {};
    for (const [wire, name] of [["input_tokens", "inputTokens"], ["output_tokens", "outputTokens"], ["total_tokens", "totalTokens"]] as const) {
        const count = value[wire];
        if (typeof count === "number" && Number.isSafeInteger(count) && count >= 0) usage[name] = count;
    }
    const details = value.input_tokens_details;
    const cached = record(details) ? details.cached_tokens : undefined;
    if (typeof cached === "number" && Number.isSafeInteger(cached) && cached >= 0 && (usage.inputTokens === undefined || cached <= usage.inputTokens)) usage.cachedInputTokens = cached;
    return Object.keys(usage).length ? usage : undefined;
}

export function toResponseInput(messages: readonly AgentRequestMessage[]): AgentResponseItem[] {
    return messages.flatMap((message): AgentResponseItem[] => {
        if (message.role === "tool") return [{
            type: "function_call_output",
            call_id: message.tool_call_id,
            output: message.content, ...(message.referenceInput ? {referenceInput: message.referenceInput} : {})
        }];
        const items: AgentResponseItem[] = message.content ? [{
            type: "message",
            role: message.role,
            content: message.content, ...(message.referenceInput ? {referenceInput: message.referenceInput} : {}), ...(message.sourceToolCallId ? {sourceToolCallId: message.sourceToolCallId} : {})
        }] : [];
        if (message.role === "assistant") for (const call of message.tool_calls ?? []) items.push({
            type: "function_call",
            call_id: call.id,
            name: call.function.name,
            arguments: call.function.arguments
        });
        return items;
    });
}

/** Final output is authoritative. Incomplete argument deltas never dispatch a tool. */
export function decodeResponseOutput(output: unknown, tools: StreamChatInput["tools"]): {
    items: AgentResponseItem[];
    content: string;
    reasoning: string;
    calls: AgentWireToolCall[]
} {
    if (!Array.isArray(output) || output.length > 256 || JSON.stringify(output).length > MAX_ENVELOPE_SIZE) throw new Error("Responses 输出信封无效或超过限制");
    let content = "", reasoning = "";
    const calls: AgentWireToolCall[] = [];
    const ids = new Set<string>();
    const items = output.map((item): AgentResponseItem => {
        if (!record(item)) throw new Error("Responses 输出项无效");
        if (item.status != null && item.status !== "completed") throw new Error("Responses 输出项尚未完成");
        const itemId = item.id === undefined ? undefined : id(item.id);
        if (itemId && ids.has(itemId)) throw new Error("Responses 输出标识重复");
        if (itemId) ids.add(itemId);
        if (item.type === "reasoning") {
            if (!Array.isArray(item.summary)) throw new Error("Responses 推理摘要格式无效");
            const summary = item.summary.map((part) => {
                if (!record(part) || part.type !== "summary_text") throw new Error("Responses 推理摘要格式无效");
                const value = text(part.text);
                reasoning += value;
                return {type: "summary_text" as const, text: value};
            });
            const encrypted = item.encrypted_content == null ? undefined : text(item.encrypted_content);
            // LobeHub drops id-only reasoning in stateless replay: it cannot be looked up.
            return {
                type: "reasoning", ...(encrypted && itemId ? {id: itemId} : {}),
                summary, ...(encrypted ? {encrypted_content: encrypted} : {})
            };
        }
        if (item.type === "message") {
            if (item.role !== "assistant" || !Array.isArray(item.content)) throw new Error("Responses 回复格式无效");
            const parts = item.content.map((part) => {
                if (!record(part) || part.type !== "output_text") throw new Error("模型拒绝回复或返回了不支持的非文本内容");
                const value = text(part.text);
                content += value;
                return {type: "output_text" as const, text: value, annotations: []};
            });
            return {
                type: "message",
                role: "assistant",
                content: parts, ...(itemId ? {id: itemId} : {}),
                status: "completed", ...(typeof item.phase === "string" ? {phase: text(item.phase, 64)} : {})
            };
        }
        if (item.type === "function_call") {
            const callId = id(item.call_id), name = text(item.name, 128), args = text(item.arguments, 32768);
            if (calls.length >= 16 || calls.some((call) => call.id === callId) || !tools?.some((tool) => tool.function.name === name)) throw new Error("Responses 请求了重复、过多或未启用的工具");
            let parsed: unknown;
            try {
                parsed = JSON.parse(args);
            } catch {
                throw new Error("工具调用参数不是完整 JSON");
            }
            if (!record(parsed)) throw new Error("工具参数必须是对象");
            calls.push({id: callId, type: "function", function: {name, arguments: args}});
            return {
                type: "function_call",
                call_id: callId,
                name,
                arguments: args, ...(itemId ? {id: itemId} : {}),
                status: "completed"
            };
        }
        throw new Error("Responses 返回了未启用的输出类型");
    });
    return {items, content, reasoning, calls};
}

/** Stateless Responses adapter: one POST, local continuation, no automatic fallback. */
export async function streamResponses(input: StreamChatInput & {
    responseItems?: AgentResponseItem[]
}, handlers: StreamChatHandlers = {}): Promise<ResponsesResult> {
    const base = normalizeBaseUrl(input.baseUrl), apiKey = input.apiKey.trim(), model = input.model.trim();
    const signal = handlers.signal;
    const startedAt = Date.now();
    let firstTokenAt: number | undefined, usage: AgentTokenUsage | undefined;
    let content = "", reasoning = "", outputBytes = 0;
    const redact = (value: string) => redactCredentials(value, apiKey).slice(0, 300);
    const result = (value: ResponsesResult): ResponsesResult => ({
        ...value, ...(usage ? {usage} : {}),
        metrics: {
            startedAt,
            endedAt: Date.now(), ...(firstTokenAt === undefined ? {} : {firstTokenAt}), ...(usage ? {usage} : {})
        }
    });
    const emit = (kind: "content" | "reasoning", value: string, streaming = true) => {
        signal?.throwIfAborted();
        if (!value) return;
        const nextBytes = outputBytes + appendedUtf8Bytes(kind === "content" ? content : reasoning, value);
        assertResponseBytes(nextBytes, MAX_ENVELOPE_SIZE);
        if (content.length + reasoning.length + value.length > MAX_ENVELOPE_SIZE) throw new Error("Responses 输出超过限制");
        outputBytes = nextBytes;
        if (streaming && firstTokenAt === undefined) firstTokenAt = Date.now();
        if (kind === "content") {
            content += value;
            handlers.onDelta?.(value);
        } else {
            reasoning += value;
            handlers.onReasoning?.(value);
        }
        signal?.throwIfAborted();
    };
    const finish = (response: unknown, via: "json" | "stream"): ResponsesResult => {
        if (!record(response)) throw new Error("Responses 缺少完整结果");
        usage = usageOf(response.usage) ?? usage;
        if (response.status !== "completed" || response.error != null) {
            const detail = record(response.error) && typeof response.error.message === "string" ? response.error.message : response.status === "incomplete" ? "回复达到限制或被过滤，内容未完成" : "Responses 执行失败或尚未完成";
            return result({
                ok: false,
                message: redact(detail),
                // Status is diagnostic metadata: never copy arbitrary provider text into saved runs.
                finishReason: typeof response.status === "string" && RESPONSE_STATUSES.has(response.status) ? response.status : undefined
            });
        }
        const parsed = decodeResponseOutput(response.output, input.tools);
        assertResponseBytes(utf8Bytes(JSON.stringify(response.output)), MAX_ENVELOPE_SIZE);
        if (!parsed.content.startsWith(content) || !parsed.reasoning.startsWith(reasoning)) throw new Error("Responses 最终内容与流事件不一致");
        // A terminal envelope is a complete payload, not evidence of first-token
        // latency. Only actual delta events establish streaming throughput timing.
        emit("reasoning", parsed.reasoning.slice(reasoning.length), false);
        emit("content", parsed.content.slice(content.length), false);
        if (!parsed.calls.length && !parsed.content.trim()) throw new Error("模型未返回有效的回答内容");
        return result({
            ok: true,
            content,
            reasoning,
            via,
            finishReason: parsed.calls.length ? "tool_calls" : "stop", ...(parsed.calls.length ? {toolCalls: parsed.calls} : {}),
            responseOutput: parsed.items
        });
    };
    try {
        signal?.throwIfAborted();
        if (!base || !apiKey || !model) throw new Error("请配置连接、API Key 和模型");
        if (!input.messages.length && !input.responseItems?.length) throw new Error("消息不能为空");
        if (input.connectorDefinitionId !== "openai-compatible" && input.connectorDefinitionId !== "aihubmix") throw new Error("当前连接尚未支持 Responses 协议");
        assertReasoningEffort({definitionId: input.connectorDefinitionId, baseUrl: base}, model, input.reasoningEffort);
        const res = await (handlers.fetchImpl ?? fetch)(`${base}/responses`, {
            method: "POST", headers: authHeaders(apiKey), signal,
            body: JSON.stringify({
                model, ...(input.maxOutputTokens ? {max_output_tokens: input.maxOutputTokens} : {}),
                input: await materializeResponseItems(input.responseItems ?? toResponseInput(input.messages), input, signal),
                stream: true,
                store: false,
                include: ["reasoning.encrypted_content"],
                ...(input.reasoningEffort !== undefined ? {
                    reasoning: {
                        effort: input.reasoningEffort,
                        summary: "auto"
                    }
                } : {reasoning: {summary: "auto"}}),
                ...(input.tools?.length ? {
                    tools: input.tools.map((tool) => ({
                        type: "function", ...tool.function,
                        strict: false
                    }))
                } : {}),
            }),
        });
        if (signal?.aborted) {
            await res.body?.cancel().catch(() => undefined);
            signal.throwIfAborted();
        }
        if (!res.ok) return result({
            ok: false,
            message: `请求失败（${res.status}）：${redact(await readErrorText(res, MAX_ERROR_BYTES, signal))}`
        });
        if (!(res.headers.get("content-type") ?? "").includes("text/event-stream")) return finish(await readResponseJson(res, MAX_JSON_BYTES, signal), "json");
        if (!res.body) throw new Error("Responses 返回了空的响应流");
        let terminal: ResponsesResult | undefined;
        const dispatch = (data: string, name: string) => {
            if (!data || data.trim() === "[DONE]") return;
            const value: unknown = JSON.parse(data);
            if (!record(value) || typeof value.type !== "string") throw new Error("Responses 流事件无效");
            if (name && name !== value.type) throw new Error("Responses 流事件类型不一致");
            if (value.type === "error") throw new Error(typeof value.message === "string" ? value.message : "Responses 返回错误");
            if (["response.completed", "response.failed", "response.incomplete"].includes(value.type)) {
                if (!record(value.response) || value.type !== `response.${value.response.status}`) throw new Error("Responses 结束事件状态不一致");
                terminal = finish(value.response, "stream");
                return;
            }
            if (value.type === "response.output_text.delta") emit("content", text(value.delta));
            if (value.type === "response.reasoning_summary_text.delta") emit("reasoning", text(value.delta));
            // Never render raw reasoning_text or encrypted_content. Tool argument
            // fragments are accepted only via the complete terminal output envelope.
            if (content.length + reasoning.length > MAX_ENVELOPE_SIZE) throw new Error("Responses 输出超过限制");
        };
        for await (const event of readSseEvents(res, signal)) {
            dispatch(event.data, event.event);
            if (terminal) break;
        }
        signal?.throwIfAborted();
        if (!terminal) throw new Error("Responses 回复流意外中断，已保留收到的内容");
        return terminal;
    } catch (error) {
        return result(isReadAbort(error, signal) ? {
            ok: false,
            message: "已停止",
            aborted: true
        } : {ok: false, message: redact(error instanceof Error ? error.message : "Responses 请求失败")});
    }
}

import {readResponseJson, ResponseLimitError} from "./boundedResponse";
import {db} from '@/db/database';
import {publicWebUrl, type WebFailure, type WebFailureCode, type WebResult, type WebSource} from '@/domain/search';
import {nowIso} from '@/lib/ids';

export interface WebSearchArgs {
    query: string;
    maxResults?: number;
    timeRange?: 'day' | 'week' | 'month' | 'year'
}

export interface TavilyOptions {
    fetchImpl?: typeof fetch;
    signal?: AbortSignal;
    timeoutMs?: number
}

const MAX_RESPONSE_BYTES = 2 * 1024 * 1024;

export function webFailure(code: WebFailureCode, message: string, serviceMayHaveRun = false): WebFailure {
    return {ok: false, code, message, serviceMayHaveRun, retrievedAt: nowIso()};
}

const record = (value: unknown): Record<string, unknown> | undefined => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : undefined;

function clean(value: unknown, max: number, key: string): string {
    if (typeof value !== 'string') return '';
    return value.split(key).join('[已隐藏]').split(encodeURIComponent(key)).join('[已隐藏]').slice(0, max);
}

function sourceUrl(value: unknown, key: string): string | undefined {
    if (typeof value !== 'string' || value.includes(key) || value.includes(encodeURIComponent(key))) return undefined;
    return publicWebUrl(value);
}

async function request(path: 'search' | 'extract' | 'usage', key: string, body: unknown, options: TavilyOptions): Promise<{
    ok: true;
    value: unknown
} | WebFailure> {
    if (options.signal?.aborted) return webFailure('cancelled', '已停止本地等待，未发送请求');
    const controller = new AbortController();
    let timedOut = false;
    const abort = () => controller.abort();
    options.signal?.addEventListener('abort', abort, {once: true});
    const timer = setTimeout(() => {
        timedOut = true;
        controller.abort();
    }, options.timeoutMs ?? 30_000);
    const mayHaveRun = path !== 'usage';
    try {
        const response = await (options.fetchImpl ?? fetch)(`https://api.tavily.com/${path}`, {
            method: path === 'usage' ? 'GET' : 'POST', credentials: 'omit', redirect: 'error',
            headers: {Authorization: `Bearer ${key}`, ...(path !== 'usage' ? {'Content-Type': 'application/json'} : {})},
            ...(path !== 'usage' ? {body: JSON.stringify(body)} : {}), signal: controller.signal,
        });
        if (!response.ok) {
            await response.body?.cancel();
            const code = response.status === 401 || response.status === 403 ? 'authentication' : response.status === 429 ? 'rate_limit' : [402, 432, 433].includes(response.status) ? 'quota' : 'http';
            const message = code === 'authentication' ? 'Tavily 鉴权失败，请检查 API Key' : code === 'rate_limit' ? '搜索服务请求过于频繁，请稍后明确发起新请求' : code === 'quota' ? '搜索服务额度不可用，请检查账户' : `搜索服务返回 HTTP ${response.status}`;
            return webFailure(code, message, mayHaveRun);
        }
        try {
            return {ok: true, value: await readResponseJson(response, MAX_RESPONSE_BYTES, controller.signal, false)};
        } catch (error) {
            if (controller.signal.aborted) throw error;
            return error instanceof ResponseLimitError ? webFailure('response_too_large', '服务响应超过 2 MiB，未读取超限内容', mayHaveRun) : webFailure('invalid_response', '搜索服务返回了无法解析的数据', mayHaveRun);
        }
    } catch {
        return webFailure(timedOut ? 'timeout' : options.signal?.aborted ? 'cancelled' : 'transport', timedOut ? '搜索服务等待超时，服务可能已处理请求；没有自动重试' : options.signal?.aborted ? '已停止本地等待，不表示服务已取消或退款' : '无法连接搜索服务（网络或跨域限制），请在连接页测试鉴权；请求可能已处理，没有自动重试', mayHaveRun);
    } finally {
        clearTimeout(timer);
        options.signal?.removeEventListener('abort', abort);
    }
}

/** Only the adapter reads saved credentials. Expected failures are complete tool results. */
export async function executeWebRequest(kind: 'search' | 'read', args: WebSearchArgs | {
    url: string
}, revision: string | undefined, options: TavilyOptions = {}): Promise<WebResult> {
    const config = await db.searchConnections.get('tavily');
    if (!config?.enabled || !config.apiKey) return webFailure('not_configured', '请在「连接 → 联网搜索」配置并启用 Tavily，然后重新发起调研');
    if (!revision || config.revision !== revision) return webFailure('configuration_changed', '搜索连接已变化，请重新准备并批准这次调研');
    const search = args as WebSearchArgs;
    const url = kind === 'read' ? publicWebUrl((args as { url: string }).url) : undefined;
    if (kind === 'read' && !url) return webFailure('invalid_response', '仅支持不含凭据的公开 HTTP(S) 网页');
    const body = kind === 'search' ? {
        query: search.query,
        max_results: search.maxResults ?? 5, ...(search.timeRange ? {time_range: search.timeRange} : {}),
        search_depth: 'basic',
        include_answer: false,
        include_raw_content: false,
        include_images: false,
        auto_parameters: false,
    } : {urls: [url], extract_depth: 'basic', format: 'markdown', include_images: false};
    const response = await request(kind === 'search' ? 'search' : 'extract', config.apiKey, body, options);
    if (!response.ok) return response;
    const data = record(response.value);
    if (!data || !Array.isArray(data.results)) return webFailure('invalid_response', '搜索服务返回的数据缺少结果列表', true);
    const requestId = clean(data.request_id, 160, config.apiKey) || undefined;
    if (kind === 'search') {
        const sources: WebSource[] = [];
        for (const raw of data.results.slice(0, 10)) {
            const item = record(raw);
            const href = item && sourceUrl(item.url, config.apiKey);
            if (!item || !href) continue;
            sources.push({
                id: `web-${sources.length + 1}`,
                title: clean(item.title, 240, config.apiKey) || new URL(href).hostname,
                url: href,
                snippet: clean(item.content, 1500, config.apiKey), ...(typeof item.published_date === 'string' ? {publishedAt: clean(item.published_date, 100, config.apiKey)} : {})
            });
            if (sources.length >= (search.maxResults ?? 5)) break;
        }
        // Each source can carry a long URL; preserve a strict total result budget too.
        const result = {
            ok: true as const,
            kind: 'search' as const,
            query: clean(search.query, 500, config.apiKey),
            sources,
            retrievedAt: nowIso(),
            requestId,
            omittedSources: 0
        };
        while (JSON.stringify(result).length > 31_000) sources.pop();
        result.omittedSources = data.results.length - sources.length;
        return result;
    }
    const item = record(data.results[0]);
    const href = item && sourceUrl(item.url, config.apiKey);
    if (!item || !href || typeof item.raw_content !== 'string' || !item.raw_content.trim()) return webFailure('extraction_failed', '未取得网页正文，可能是页面不可访问或提取失败；没有自动重试', true);
    const result = {
        ok: true as const,
        kind: 'read' as const,
        requestedUrl: url!,
        url: href,
        retrievedAt: nowIso(),
        text: clean(item.raw_content, 24_000, config.apiKey),
        availableLength: item.raw_content.length,
        truncated: item.raw_content.length > 24_000,
        coverage: 'provider_extraction' as const,
        requestId
    };
    while (JSON.stringify(result).length > 60_000) {
        result.text = result.text.slice(0, Math.floor(result.text.length * 0.8));
        result.truncated = true;
    }
    return result;
}

export async function testSearchConnection(apiKey?: string, options: TavilyOptions = {}): Promise<{
    ok: boolean;
    message: string
}> {
    const key = apiKey?.trim() || (await db.searchConnections.get('tavily'))?.apiKey;
    if (!key || key.length > 2048 || /\s/.test(key)) return {ok: false, message: '请填写 Tavily API Key'};
    const result = await request('usage', key, undefined, options);
    if (!result.ok) return {ok: false, message: result.message};
    if (!record(result.value)) return {ok: false, message: '鉴权接口返回无效数据'};
    return {ok: true, message: '鉴权读取成功；未执行搜索，搜索与网页读取权限以实际调用为准'};
}

import {MAX_AUDIO_BYTES} from "@/lib/resource/limits";
export type RecordingState =
    "idle"
    | "requesting"
    | "recording"
    | "stopping"
    | "audition"
    | "kept"
    | "discarded"
    | "error";

export interface RecorderOptions {
    onState?: (state: RecordingState) => void;
    onError?: (error: Error) => void;
}

export interface RecorderDependencies {
    devices: Pick<MediaDevices, "getUserMedia">;
    isTypeSupported: (mime: string) => boolean;
    createRecorder: (stream: MediaStream, options: MediaRecorderOptions) => MediaRecorder;
    createContext: () => AudioContext;
    now: () => number;
}

export const RECORDING_MIME_TYPES = ["audio/webm;codecs=opus", "audio/ogg;codecs=opus", "audio/mp4", "audio/webm"] as const;

/** Enumeration never requests permission; labels may be blank until Start is clicked. */
export async function listMicrophones(): Promise<MediaDeviceInfo[]> {
    if (!navigator.mediaDevices?.enumerateDevices) throw new Error("当前浏览器不支持麦克风设备选择");
    return (await navigator.mediaDevices.enumerateDevices()).filter((device) => device.kind === "audioinput");
}

function browserDependencies(): RecorderDependencies {
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") throw new Error("当前环境不支持录音，请使用 HTTPS 或本机浏览器");
    return {
        devices: navigator.mediaDevices,
        isTypeSupported: (mime) => MediaRecorder.isTypeSupported(mime),
        createRecorder: (stream, options) => new MediaRecorder(stream, options),
        createContext: () => new AudioContext(),
        now: () => performance.now()
    };
}

/** Call start only from an explicit recording gesture, never on mount or from Agent tools. */
export class MicrophoneRecorder {
    state: RecordingState = "idle";
    private dependencies: RecorderDependencies | undefined;
    private recorder: MediaRecorder | undefined;
    private stream: MediaStream | undefined;
    private context: AudioContext | undefined;
    private analyser: AnalyserNode | undefined;
    private analysisSource: MediaStreamAudioSourceNode | undefined;
    private meterData: Float32Array<ArrayBuffer> | undefined;
    private chunks: Blob[] = [];
    private chunkBytes = 0;
    private epoch = 0;
    private disposed = false;
    private startedAt = 0;
    private stoppedAt = 0;
    private completed: Blob | undefined;
    private completion: Promise<Blob> | undefined;
    private resolve: ((blob: Blob) => void) | undefined;
    private reject: ((error: Error) => void) | undefined;
    private endedListeners: { track: MediaStreamTrack; listener: () => void }[] = [];

    constructor(private readonly options: RecorderOptions = {}, dependencies?: RecorderDependencies) {
        this.dependencies = dependencies;
    }

    get elapsedSec() {
        if (!this.dependencies || !["recording", "stopping", "audition", "kept"].includes(this.state)) return 0;
        return Math.max(0, ((this.state === "recording" ? this.dependencies.now() : this.stoppedAt) - this.startedAt) / 1000);
    }

    get blob() {
        return this.completed;
    }

    async start(deviceId?: string): Promise<void> {
        if (this.disposed) throw new Error("录音器已关闭");
        if (["requesting", "recording", "stopping"].includes(this.state)) throw new Error("已有录音正在进行");
        if (this.state === "audition") throw new Error("请先保留或舍弃当前录音");
        this.dependencies ??= browserDependencies();
        const deps = this.dependencies;
        const epoch = ++this.epoch;
        this.completed = undefined;
        this.chunks = [];
        this.chunkBytes = 0;
        this.change("requesting");
        this.completion = new Promise<Blob>((resolve, reject) => {
            this.resolve = resolve;
            this.reject = reject;
        });
        // Device failure may occur before the UI calls stop; retain rejection for that call.
        void this.completion.catch(() => undefined);
        try {
            this.context = deps.createContext();
            const resume = this.context.resume();
            void resume.catch(() => undefined);
            const stream = await deps.devices.getUserMedia({
                audio: {
                    ...(deviceId ? {deviceId: {exact: deviceId}} : {}),
                    echoCancellation: false,
                    noiseSuppression: false,
                    autoGainControl: false
                }
            });
            if (epoch !== this.epoch || this.disposed) {
                stream.getTracks().forEach((track) => track.stop());
                return;
            }
            this.stream = stream;
            await resume;
            if (epoch !== this.epoch || this.disposed) return;
            const mimeType = RECORDING_MIME_TYPES.find((mime) => deps.isTypeSupported(mime));
            const recorder = deps.createRecorder(stream, mimeType ? {mimeType} : {});
            this.recorder = recorder;
            this.analyser = this.context!.createAnalyser();
            this.analyser.fftSize = 1024;
            this.meterData = new Float32Array(this.analyser.fftSize);
            this.analysisSource = this.context!.createMediaStreamSource(stream);
            this.analysisSource.connect(this.analyser); // Intentionally no speaker monitoring.
            for (const track of stream.getAudioTracks()) {
                const listener = () => {
                    if (epoch === this.epoch && this.state === "recording") this.fail(new Error("麦克风已断开，未保存当前录音"));
                };
                track.addEventListener("ended", listener);
                this.endedListeners.push({track, listener});
            }
            recorder.ondataavailable = (event) => {
                if (epoch !== this.epoch || !event.data.size) return;
                this.chunkBytes += event.data.size;
                if (this.chunkBytes > MAX_AUDIO_BYTES) {
                    this.fail(new Error("本次录音超过 32 MB，请分段录制"));
                    return;
                }
                this.chunks.push(event.data);
            };
            recorder.onerror = () => {
                if (epoch === this.epoch) this.fail(new Error("录音设备发生错误，未保存当前录音"));
            };
            recorder.onstop = () => {
                if (epoch !== this.epoch) return;
                this.stoppedAt = deps.now();
                this.releaseCapture();
                const mime = recorder.mimeType || this.chunks[0]?.type;
                const blob = new Blob(this.chunks, {type: mime || "application/octet-stream"});
                this.chunks = [];
                this.recorder = undefined;
                if (!blob.size) {
                    this.fail(new Error("未录到声音，请检查麦克风后重试"));
                    return;
                }
                this.completed = blob;
                this.change("audition");
                this.resolve?.(blob);
                this.resolve = undefined;
                this.reject = undefined;
            };
            recorder.start(1000);
            this.startedAt = deps.now();
            this.change("recording");
        } catch (error) {
            if (epoch !== this.epoch || this.disposed) return;
            const failure = error instanceof Error ? error : new Error("无法访问麦克风");
            this.fail(failure);
            throw failure;
        }
    }

    stop(): Promise<Blob> {
        if (this.state === "audition" && this.completed) return Promise.resolve(this.completed);
        if (this.state === "stopping" && this.completion) return this.completion;
        if (this.state !== "recording" || !this.recorder || !this.completion) return Promise.reject(new Error("没有正在进行的录音"));
        this.stoppedAt = this.dependencies!.now();
        this.change("stopping");
        try {
            this.recorder.stop();
        } catch (error) {
            this.fail(error instanceof Error ? error : new Error("无法结束录音"));
        }
        return this.completion;
    }

    /** UI validates/decode and durably saves the Blob before marking it kept. */
    markKept() {
        if (this.state !== "audition") throw new Error("录音尚未完成");
        this.change("kept");
    }

    readLevel(): number {
        if (!this.analyser || !this.meterData) return 0;
        this.analyser.getFloatTimeDomainData(this.meterData);
        return Math.sqrt(this.meterData.reduce((sum, value) => sum + value * value, 0) / this.meterData.length);
    }

    discard() {
        this.epoch++;
        if (this.recorder?.state !== "inactive") {
            try {
                this.recorder?.stop();
            } catch { /* Already stopped. */
            }
        }
        this.releaseCapture();
        this.recorder = undefined;
        this.chunks = [];
        this.completed = undefined;
        this.reject?.(new DOMException("录音已舍弃", "AbortError"));
        this.resolve = undefined;
        this.reject = undefined;
        this.change("discarded");
    }

    dispose() {
        this.disposed = true;
        this.discard();
    }

    private change(state: RecordingState) {
        this.state = state;
        this.options.onState?.(state);
    }

    private releaseCapture() {
        for (const {track, listener} of this.endedListeners) track.removeEventListener("ended", listener);
        this.endedListeners = [];
        for (const track of this.stream?.getTracks() ?? []) track.stop();
        this.stream = undefined;
        this.analysisSource?.disconnect();
        this.analyser?.disconnect();
        this.analysisSource = undefined;
        this.analyser = undefined;
        this.meterData = undefined;
        if (this.context && this.context.state !== "closed") void this.context.close().catch(() => undefined);
        this.context = undefined;
    }

    private fail(error: Error) {
        this.epoch++;
        if (this.recorder?.state !== "inactive") {
            try {
                this.recorder?.stop();
            } catch { /* Device may already be gone. */
            }
        }
        this.releaseCapture();
        this.recorder = undefined;
        this.chunks = [];
        this.completed = undefined;
        this.reject?.(error);
        this.resolve = undefined;
        this.reject = undefined;
        this.change("error");
        this.options.onError?.(error);
    }
}

